CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE resources(id text PRIMARY KEY,name text NOT NULL,timezone text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE appointment_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),idempotency_key text UNIQUE NOT NULL,source_event_id text NOT NULL,channel text NOT NULL,payload jsonb NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),idempotency_key text UNIQUE NOT NULL,customer_id text NOT NULL,resource_id text NOT NULL REFERENCES resources(id),service_type text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,timezone text NOT NULL,estimated_value numeric(12,2) NOT NULL DEFAULT 0,status text NOT NULL,hold_expires_at timestamptz,consent_to_reminders boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at));
CREATE EXTENSION IF NOT EXISTS btree_gist;
ALTER TABLE appointments ADD CONSTRAINT no_active_overlap EXCLUDE USING gist(resource_id WITH =,tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE(status IN('held','confirmed','rebooked'));
CREATE TABLE waitlist_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id text NOT NULL,resource_id text NOT NULL REFERENCES resources(id),service_type text NOT NULL,preferred_start timestamptz,preferred_end timestamptz,priority integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'waiting',offer_expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),appointment_id uuid REFERENCES appointments(id),kind text NOT NULL,due_at timestamptz NOT NULL,attempt_number integer NOT NULL,status text NOT NULL,provider text NOT NULL,error_code text,next_retry_at timestamptz,UNIQUE(appointment_id,kind,attempt_number));
CREATE TABLE attendance_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),appointment_id uuid UNIQUE NOT NULL REFERENCES appointments(id),outcome text NOT NULL CHECK(outcome IN('completed','no_show')),recorded_by text NOT NULL,occurred_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE recovery_offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),appointment_id uuid NOT NULL REFERENCES appointments(id),customer_id text NOT NULL,status text NOT NULL,not_before timestamptz NOT NULL,expires_at timestamptz,estimated_recoverable_value numeric(12,2) NOT NULL,evidence_type text NOT NULL DEFAULT 'simulated',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE dead_letter_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_type text NOT NULL,entity_id uuid,reason text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log(id bigserial PRIMARY KEY,appointment_id uuid REFERENCES appointments(id),actor text NOT NULL,action text NOT NULL,evidence_type text NOT NULL CHECK(evidence_type IN('simulated','provider_verified')),details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_appointments_due ON appointments(status,starts_at);CREATE INDEX idx_waitlist_match ON waitlist_entries(status,resource_id,service_type,priority,created_at);CREATE INDEX idx_notifications_due ON notification_attempts(status,next_retry_at,due_at);
